const magicDice = {1:[6,5,3,1],2:[3],3:[6,5,4,3],4:[6,4],5:[6,5,4,3,2,1],6:[6,5,4,3,2],7:[6,4],8:[6,4,2],9:[6,5,3],10:[],11:[6,3],12:[6,5,4,3],13:[],14:[6,5,4,2],15:[],16:[6,5,4,3],17:[6,5,4,3,2,1],18:[6],19:[6,3],20:[6,4,3],24:[6,3],28:[5],29:[6,3],30:[6,4],31:[6,5,4,3,1],32:[6,4,2],33:[6,5,4,3,2,1],34:[5,4,3,2,1],35:[6,3],36:[6,4,2],37:[6,3],38:[6,3],39:[6,5,4,3,2,1],40:[6,5,4,3,2],41:[6,5,4,3]};

const cards = definitions.map(d => {
  const b = d.base ? structuredClone(old[d.base-1]) : {};
  const id = String(30000000+d.n);
  const element = d.element || b.element;
  const name = d.name || b.name;
  const slug = d.base ? b.slug : `${String(d.n).padStart(2,'0')}_${element}_${name.replace(/[^A-Z0-9]+/g,'_')}`;
  const role = d.role;
  const canGuard = role===1 || !!d.guard;
  const canHeal = !!d.heal;
  const panels = {};
  // Start each face within the role's spreadsheet interval, then replace selected faces with actions.
  for(const stat of ['atk','defense']) {
    panels[stat] = max[role][stat].map((v,i)=>v-4-((d.n*3+i*2+(stat==='defense'?5:0))%7));
    for(const [i,effect] of Object.entries(specials[d.n]?.[stat] || {})) panels[stat][i] = effect;
  }
  if(d.n===1) { panels.atk=[202,167,'retry',84,'mana',29]; panels.defense=[200,167,'retry',100,59,11]; }
  const source = d.source || `${b.source} ; V2/donnees/cartes.json ${b.id} ; scene conservee, profil reequilibre V3`;
  const copy = !!d.base && !d.redraw;
  const magic = (magicDice[d.n] || []).filter(die=>element!=='NONE' && typeof panels.atk[6-die]==='number');
  const barriers = element==='NONE' ? [] : (b.barriers || (role===5?[6,3]:role===1?[5,2]:[4])).filter(die=>typeof panels.defense[6-die]==='number');
  const c = {
    element, name, race:d.race||b.race, faction:d.faction||b.faction,
    job:d.job||b.job, title:d.title||b.title,
    positions:d.n===1||d.n===14?[3,4]:[role], weapon:d.weapon===undefined?b.weapon:weapons[d.weapon],
    ...panels, magic, barriers, text:d.text||b.text,
    source, color:elements[element].color, hue:elements[element].hue,
    advantage:element==='RAINBOW'?40:element==='NONE'?0:(b.advantage??30),
    disadvantage:element==='NONE'||element==='RAINBOW'?0:(b.disadvantage??30),
    id, slug, art:`V3/assets/illustrations/${slug}.png`, reference:null,
    weapon_index:d.weapon===undefined?b.weapon_index:d.weapon,
    visual_revision:'V3-repertoire-41', barcode_style:'spectrum_dark',
    characterId:normalize(name), role, sentry:element!=='NONE', canGuard, canHeal,
    story_scene:d.scene, prompt:style+d.pose+(element==='NONE'?' Sans cristal : aucun halo ni barriere elementaire.':''),
    source_art:copy?b.art:null, art_action:copy?'copy':d.redraw?'redraw':'generate',
    previous_id:d.base?b.id:null,
    replaces_v2_id:[15,16,17,20].includes(d.n)?String(d.n).padStart(8,'0'):null,
    aliases:d.aliases||[],
    balance_source:'main/Kalistar.xlsx, Capacite base ; ajustements V3 decrits dans DECISIONS_NARRATIVES.md'
  };
  return c;
});

const sceneRevisions=read('V3/donnees/revision_buffs_scenes_profils.json');
for(const c of cards){
  const revision=sceneRevisions[c.id];if(!revision)continue;
  const {pose,...fields}=revision;
  Object.assign(c,fields);
  c.prompt='Peinture narrative Kalistar, reference Momo ; touches visibles, matieres usees, anatomie lisible, emotion. Aucun texte, cadre ou interface. '+pose;
  c.visual_revision='V3-buffs-scenes-20260914';
  c.source+=' ; revision de scene explicite utilisateur 2026-09-14';
  c.art_action='redraw';c.source_art=null;
}

