arenaScenes.astraball.prompt='Le terrain d Astraball de Zarok : terrain sportif improvise mais spacieux en terre compacte pres de la grande place du village, entre des maisons taillees dans le canyon. Le sport utilise pieds et mains, comme un melange de basket et de contact. A chaque extremite, un PANIER EN FORME DE U INVERSE, arche etroite arrondie avec deux montants et filet de reception, de taille humaine proportionnee au terrain ; PAS de cercle de basket, pas anneaux, pas cage de football. Marques au sol simples pour la zone du pilier qui ne peut la quitter et les transitions des cinq roles, sans texte ni chiffres. Gradins bas tailles dans la roche, structures robustes, une balle pres du bord, drapeaux vert et blanc. Grand ciel lumineux, ombres franches, aucun joueur ni foule ni magie. Centre entierement libre. Dimensions exactes, nombre et disposition des paniers sont une extrapolation visuelle, pas une regle additionnelle.';
for(const a of arenas) {
  const info=arenaScenes[a.id];
  const line=info.anchor===null?-1:historyLines.findLastIndex(l=>l.includes(info.anchor));
  if(info.anchor!==null && line<0) throw new Error(`Missing history anchor for ${a.id}`);
  const header=line<0?null:historyLines.slice(0,line+1).findLast(l=>l.startsWith('SOURCE: '));
  a.story_scene=info.scene;
  a.prompt=arenaStyle+' Haute resolution, composition large en perspective HAUTE TROIS-QUARTS, camera au-dessus du sol regardant obliquement vers le bas. Au moins la moitie centrale de la scene est un sol jouable simple destine a recevoir plus tard des cartes superposees, sans dessiner ces cartes. Details concentres en peripherie. Pas de bokeh, pas d orbes decoratives, pas de pastilles lumineuses, pas d arene romaine generique. '+info.prompt;
  a.narrative_status=info.status;
  a.source_history={file:line<0?null:'V3/sources/histoire.txt',docx:header?header.slice(8):null,section:info.section,lineStart:line<0?null:line+1,lineEnd:line<0?null:Math.min(line+8,historyLines.length),anchor:info.anchor};
  a.production={action:a.id==='z13'?'parent-in-progress':a.id==='ruins'?'reuse':'generate',original:a.id==='z13'?null:a.id==='ruins'?'V3/site/assets/arena.webp':`V3/assets/arenas/${a.id}.png`,destination:`V3/site/${a.image}`,doNotModify:a.id==='z13'};
}

